import csvfrom openpyxl import load_workbookdef excel_read(filename):    """считывает финансовые операции из XLSX-файла"""    workbook = load_workbook(filename)    sheet = workbook.active  # Выбираем активную таблицу    # Получаем заголовки столбцов    headers = [cell.value for cell in sheet[1]]    # Читаем данные начиная со второй строки    data = []    for row in sheet.iter_rows(min_row=2, values_only=True):        row_data = dict(zip(headers, row))        data.append(row_data)    return datadef csv_read():    """считывает финансовые операции из CSV-файла"""    with open('transactions.csv', mode='r', encoding='utf-8') as file:        # Создаем объект DictReader для чтения файла        reader = csv.DictReader(file)        # Преобразуем содержимое файла в список словарей        data = list(reader)    # Выводим результат    return data# print(csv_read())print(excel_read('transactions_excel.xlsx'))def mlev(s):    w = excel_read(s)    keys = ['date', 'state', 'description', 'amount', 'currency_name', 'from', 'to']    filtered_data = {k: w.get(k, None) for k in keys}# mlev('transactions_excel.xlsx')# print(type(mlev('transactions_excel.xlsx')))